gh api graphql -f query='
query { 
  repository(owner: "ravencloak-org", name: "Raven") { 
    codeScanningAlerts: vulnerabilityAlerts(first: 100) { totalCount }
  }
}' 2>&1 | head -5
echo '---SARIF-DOWNLOAD---'
# Get the SARIF for the Python analysis with results
gh api 'repos/ravencloak-org/Raven/code-scanning/analyses/1228191964' --jq '.' 2>&1 | head -20
echo '---WEB-PAGE-AUTH---'
gh auth token | head -c 4 && echo "<token>"
echo '---ALL-WITHOUT-FILTER---'
gh api 'repos/ravencloak-org/Raven/code-scanning/alerts' --paginate 2>&1 | python3 -c "
import json, sys
data = sys.stdin.read()
try:
    arr = json.loads(data)
    print(f'total: {len(arr)}')
    for a in arr:
        print(f'#{a[\"number\"]}\t{a[\"state\"]}\t{a[\"tool\"][\"name\"]}\t{a[\"rule\"][\"id\"]}\t{a[\"most_recent_instance\"][\"location\"].get(\"path\",\"-\")}')
except Exception as e:
    print(f'parse err: {e}')"

